using System;using System.Text;using System.Collections;using System.Collections.Generic;
public static class SourceTaskPresentation{
 static string S(Dictionary<string,object>d,string k){object v;return d.TryGetValue(k,out v)&&v!=null?Convert.ToString(v):"unknown";}
 static IEnumerable<object>A(Dictionary<string,object>d,string k){object v;if(d.TryGetValue(k,out v)&&v is IEnumerable&&!(v is string)&&!(v is IDictionary))foreach(var x in(IEnumerable)v)yield return x;}
 public static string Describe(Dictionary<string,object>direct){object value;if(!direct.TryGetValue("question_task_binding",out value)||!(value is Dictionary<string,object>))return "";var chain=(Dictionary<string,object>)value;var b=new StringBuilder("ВОПРОС → ЗАДАЧА → ДОКУМЕНТИРОВАННАЯ ФУНКЦИЯ: "+S(chain,"status")+"\r\n");b.AppendLine("Task: "+S(chain,"routed_task")).AppendLine(S(chain,"source_task_scope"));foreach(var x in A(chain,"question_references")){var r=(Dictionary<string,object>)x;b.AppendLine(S(r,"evidence_id")+" | "+S(r,"url")+" | "+S(r,"scope")+" | "+S(r,"title")).AppendLine("Saved observation SHA256: "+S(r,"source_row_sha256"));if(r.ContainsKey("context_text")&&r["context_text"]!=null)b.AppendLine("Saved normalized question body: "+S(r,"context_text")).AppendLine("Context SHA256: "+S(r,"context_text_sha256"));}foreach(var x in A(chain,"document_references")){var d=(Dictionary<string,object>)x;b.AppendLine("Document: "+S(d,"source_url")+" | "+S(d,"documented_scope")+" | record SHA256 "+S(d,"record_sha256"));if(d.ContainsKey("error")&&d["error"]!=null)b.AppendLine("Source error: "+S(d,"error"));}foreach(var x in A(chain,"functional_profile_references")){var d=(Dictionary<string,object>)x;b.AppendLine("Function profile: "+S(d,"source_url")+" | record SHA256 "+S(d,"record_sha256"));}foreach(var x in A(chain,"rejected_equivalences"))b.AppendLine("Rejected equivalence: "+Convert.ToString(x));foreach(var x in A(chain,"requirement_bindings")){var r=(Dictionary<string,object>)x;b.AppendLine("Requirement input: "+S(r,"scope")+" | "+S(r,"field")+" | "+S(r,"quote")+" | ["+S(r,"start")+","+S(r,"end")+") | normalized field SHA256: "+S(r,"text_sha256"));}foreach(var x in A(chain,"needed_evidence"))b.AppendLine("Needed evidence: "+Convert.ToString(x));return b.ToString();}
}
